/* ---------- photos (randomuser.me portraits, picsum.photos landscapes) ---------- */
const PHOTOS = {
  'Tim':'data:image/jpeg;base64,',
  'Martijn':'data:image/jpeg;base64,',
  'Max':'data:image/jpeg;base64,',
  'Thomas':'data:image/jpeg;base64,',
  'Emma':'data:image/jpeg;base64,',
  'Mom':'data:image/jpeg;base64,',
  'Dad':'data:image/jpeg;base64,',
  'Sophie':'data:image/jpeg;base64,',
  'Lotte':'data:image/jpeg;base64,',
  'Study Group':'data:image/jpeg;base64,',
};
const SUNSET = 'data:image/jpeg;base64,';
function faceImg(name){
  const src = PHOTOS[name] || PHOTOS[Object.keys(PHOTOS).find(k => first(k) === name)];
  return src ? `<img src="${src}" alt="">` : `<span class="ini">${esc(name.trim()[0] || '?').toUpperCase()}</span>`;
}
